module benchmark/solution

import std/env (getArgs)
import std/fs (readFile)
import std/string (split, trim, stringToInt)
import std/option (Some, None)

func sumLines(lines: [string]) -> int =
  match lines {
    [] => 0,
    line :: rest => {
      let t = trim(line);
      if t == "" then sumLines(rest)
      else match stringToInt(t) {
        Some(n) => n + sumLines(rest),
        None => sumLines(rest)
      }
    }
  }

export func main() -> () ! {IO, FS, Env} {
  let args = getArgs();
  match args {
    filename :: _ => {
      let content = readFile(filename);
      let lines = split(content, "\n");
      println(show(sumLines(lines)))
    },
    _ => println("Usage: program <filename>")
  }
}

module benchmark/solution

import std/fs (readFile, writeFile)
import std/json (decode, getString, getInt, getArray)
import std/result (Result, Ok, Err)
import std/option (Some, None)
import std/string (chars)
import std/list (length as listLength)

pure func countDotsChars(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => if c == "." then 1 + countDotsChars(rest) else countDotsChars(rest)
  }

pure func countDots(s: string) -> int =
  countDotsChars(chars(s))

pure func validPort(port: int) -> bool =
  port >= 1024 && port <= 65535

pure func validVersion(version: string) -> bool =
  countDots(version) == 2

pure func validFeaturesCount(count: int) -> bool =
  count > 0

func loadAndValidateConfig() -> Result[{app_name: string, version: string, port: int, feature_count: int}, string] ! {FS} {
  let content = readFile("app_config.json");
  match decode(content) {
    Ok(json) => match getString(json, "app_name") {
      Some(appName) => match getString(json, "version") {
        Some(version) => match getInt(json, "port") {
          Some(port) => match getArray(json, "features") {
            Some(features) => {
              let featureCount = listLength(features);
              if not validPort(port) then Err("Invalid port")
              else if not validVersion(version) then Err("Invalid version")
              else if not validFeaturesCount(featureCount) then Err("Invalid features")
              else Ok({app_name: appName, version: version, port: port, feature_count: featureCount})
            },
            None => Err("Missing features")
          },
          None => Err("Missing port")
        },
        None => Err("Missing version")
      },
      None => Err("Missing app_name")
    },
    Err(msg) => Err(msg)
  }
}

export func main() -> () ! {IO, FS} {
  let configJson = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  writeFile("app_config.json", configJson);
  match loadAndValidateConfig() {
    Ok(config) => println("Loaded ${config.app_name} v${config.version} on port ${config.port} with ${config.feature_count} features"),
    Err(msg) => println("Error: ${msg}")
  }
}

