import json
import os

def create_config_file():
    config = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "port": 8080,
        "features": ["logging", "auth", "api"]
    }
    with open("app_config.json", "w") as f:
        json.dump(config, f, indent=2)

def validate_version(version):
    parts = version.split(".")
    return len(parts) == 3 and all(part.isdigit() for part in parts)

def validate_port(port):
    return 1024 <= port <= 65535

def validate_features(features):
    return len(features) > 0

def load_and_validate_config(filepath):
    with open(filepath, "r") as f:
        content = f.read()

    config = json.loads(content)

    if "port" not in config:
        raise ValueError("Missing 'port' field")
    if not isinstance(config["port"], int):
        raise ValueError("'port' must be an integer")
    if not validate_port(config["port"]):
        raise ValueError("Port must be between 1024 and 65535")

    if "version" not in config:
        raise ValueError("Missing 'version' field")
    if not isinstance(config["version"], str):
        raise ValueError("'version' must be a string")
    if not validate_version(config["version"]):
        raise ValueError("Version must be in X.Y.Z format with exactly two dots")

    if "features" not in config:
        raise ValueError("Missing 'features' field")
    if not isinstance(config["features"], list):
        raise ValueError("'features' must be a list")
    if not validate_features(config["features"]):
        raise ValueError("Features list must not be empty")

    return config

def main():
    config_file = "app_config.json"

    if not os.path.exists(config_file):
        create_config_file()

    config = load_and_validate_config(config_file)

    result = f"Loaded {config['app_name']} v{config['version']} on port {config['port']} with {len(config['features'])} features"
    print(result)

if __name__ == "__main__":
    main()

