type BST = Leaf | Node(BST, int, BST)

pure func insert(tree: BST, val: int) -> BST =
  match tree {
    Leaf => Node(Leaf, val, Leaf),
    Node(left, v, right) =>
      if val < v then Node(insert(left, val), v, right)
      else if val > v then Node(left, v, insert(right, val))
      else Node(left, v, right)
  }

pure func contains(tree: BST, val: int) -> bool =
  match tree {
    Leaf => false,
    Node(left, v, right) =>
      if val == v then true
      else if val < v then contains(left, val)
      else contains(right, val)
  }

pure func size(tree: BST) -> int =
  match tree {
    Leaf => 0,
    Node(left, _, right) => 1 + size(left) + size(right)
  }

pure func isBST(tree: BST, lo: int, hi: int) -> bool =
  match tree {
    Leaf => true,
    Node(left, v, right) =>
      v > lo && v < hi && isBST(left, lo, v) && isBST(right, v, hi)
  }

pure func insertPreservesBST(val: int) -> bool =
  isBST(insert(Leaf, val), -999999, 999999)

pure func insertThenFind(val: int) -> bool =
  contains(insert(Leaf, val), val)

