import sys

class BST:
    def __init__(self, value: int, left: 'BST' = None, right: 'BST' = None):
        self.value = value
        self.left = left
        self.right = right

Leaf = None

def insert(tree: BST, value: int) -> BST:
    if tree is None:
        return BST(value)
    if value < tree.value:
        return BST(tree.value, insert(tree.left, value), tree.right)
    elif value > tree.value:
        return BST(tree.value, tree.left, insert(tree.right, value))
    return tree

def contains(tree: BST, value: int) -> bool:
    if tree is None:
        return False
    if value == tree.value:
        return True
    elif value < tree.value:
        return contains(tree.left, value)
    return contains(tree.right, value)

def size(tree: BST) -> int:
    if tree is None:
        return 0
    return 1 + size(tree.left) + size(tree.right)

def isBST(tree: BST, min_val: int, max_val: int) -> bool:
    if tree is None:
        return True
    if tree.value <= min_val or tree.value >= max_val:
        return False
    return isBST(tree.left, min_val, tree.value) and isBST(tree.right, tree.value, max_val)

def insertPreservesBST(value: int) -> bool:
    tree = None
    for v in [10, 5, 15, 3, 7, 12, 20]:
        tree = insert(tree, v)
    tree = insert(tree, value)
    return isBST(tree, -999999, 999999)

def insertThenFind(value: int) -> bool:
    tree = None
    tree = insert(tree, value)
    return contains(tree, value)

