module benchmark/solution

import std/string (chars, stringToInt, join)
import std/list (foldl, length, map)

-- Run-length encode a string
pure func encode(s: string) -> string =
  let cs = chars(s) in
  let runs = buildRuns(cs) in
  join("", map(\run. encodeRun(run), runs))

-- Build list of (char, count) runs
pure func buildRuns(cs: [string]) -> [{ch: string, cnt: int}] =
  match cs {
    [] => [],
    c :: rest => buildRunsAcc(rest, c, 1, [])
  }

pure func buildRunsAcc(cs: [string], cur: string, cnt: int, acc: [{ch: string, cnt: int}]) -> [{ch: string, cnt: int}] =
  match cs {
    [] => acc ++ [{ch: cur, cnt: cnt}],
    c :: rest =>
      if c == cur
        then buildRunsAcc(rest, cur, cnt + 1, acc)
        else buildRunsAcc(rest, c, 1, acc ++ [{ch: cur, cnt: cnt}])
  }

pure func encodeRun(run: {ch: string, cnt: int}) -> string =
  "${show(run.cnt)}${run.ch}"

-- Run-length decode a string
pure func decode(s: string) -> string =
  let cs = chars(s) in
  decodeLoop(cs, "")

pure func decodeLoop(cs: [string], acc: string) -> string =
  match cs {
    [] => acc,
    c :: rest =>
      if isDigit(c)
        then
          let numResult = collectDigits(cs, "") in
          let numStr = numResult.digits in
          let remaining = numResult.rest in
          match remaining {
            [] => acc,
            ch :: afterCh =>
              match stringToInt(numStr) {
                Some(n) => decodeLoop(afterCh, "${acc}${repeatStr(ch, n)}"),
                None => decodeLoop(afterCh, acc)
              }
          }
        else decodeLoop(rest, "${acc}${c}")
  }

pure func collectDigits(cs: [string], acc: string) -> {digits: string, rest: [string]} =
  match cs {
    [] => {digits: acc, rest: []},
    c :: rest =>
      if isDigit(c)
        then collectDigits(rest, "${acc}${c}")
        else {digits: acc, rest: cs}
  }

pure func isDigit(c: string) -> bool =
  c == "0" || c == "1" || c == "2" || c == "3" || c == "4" ||
  c == "5" || c == "6" || c == "7" || c == "8" || c == "9"

pure func repeatStr(c: string, n: int) -> string =
  if n <= 0 then "" else "${c}${repeatStr(c, n - 1)}"

-- Roundtrip: decode(encode(s)) == s
pure func roundtrip(s: string) -> bool =
  decode(encode(s)) == s

-- Encode a single character
pure func singleCharEncode(c: string) -> string =
  encode(c)

export func main() -> () ! {IO} {
  println(encode("aaabbc"));
  println(encode("xyz"));
  println(decode("3a2b1c"));
  println(decode("1x1y1z"));
  println(show(roundtrip("hello")));
  println(singleCharEncode("q"))
}

