def encode(s):
    """Run-length encode a string."""
    if not s:
        return ""

    result = []
    count = 1
    current_char = s[0]

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(str(count) + current_char)
            current_char = char
            count = 1

    result.append(str(count) + current_char)
    return "".join(result)


def decode(s):
    """Run-length decode a string."""
    if not s:
        return ""

    result = []
    i = 0

    while i < len(s):
        count_str = ""
        while i < len(s) and s[i].isdigit():
            count_str += s[i]
            i += 1

        if i < len(s):
            char = s[i]
            result.append(char * int(count_str))
            i += 1

    return "".join(result)


def roundtrip(s):
    """Proof that decode(encode(s)) == s."""
    return decode(encode(s)) == s


def singleCharEncode(s):
    """Proof that a single character encodes to 1 + character."""
    return encode(s) == "1" + s


print(encode("aaabbc"))
print(encode("xyz"))
print(decode("3a2b1c"))
print(decode("1x1y1z"))
print(roundtrip("hello"))
print(singleCharEncode("q"))

