module benchmark/solution
import std/string (chars, repeat)

func digit(one: string, five: string, ten: string, d: int) -> string ! {} =
  if d == 0 then ""
  else if d == 1 then one
  else if d == 2 then "${one}${one}"
  else if d == 3 then "${one}${one}${one}"
  else if d == 4 then "${one}${five}"
  else if d == 5 then five
  else if d == 6 then "${five}${one}"
  else if d == 7 then "${five}${one}${one}"
  else if d == 8 then "${five}${one}${one}${one}"
  else "${one}${ten}"

export func toRoman(n: int) -> string ! {} {
  if n < 1 || n > 3999 then ""
  else {
    let thousands = n / 1000;
    let hundreds = (n % 1000) / 100;
    let tens = (n % 100) / 10;
    let ones = n % 10;
    let m = repeat("M", thousands);
    let c = digit("C", "D", "M", hundreds);
    let x = digit("X", "L", "C", tens);
    let i = digit("I", "V", "X", ones);
    "${m}${c}${x}${i}"
  }
}

func romanValue(c: string) -> int ! {} =
  if c == "I" then 1
  else if c == "V" then 5
  else if c == "X" then 10
  else if c == "L" then 50
  else if c == "C" then 100
  else if c == "D" then 500
  else if c == "M" then 1000
  else 0

func fromChars(cs: [string]) -> int ! {} =
  match cs {
    [] => 0,
    c :: rest => {
      let current = romanValue(c);
      match rest {
        [] => current,
        nextChar :: more => {
          let next = romanValue(nextChar);
          if current < next then (next - current) + fromChars(more) else current + fromChars(rest)
        }
      }
    }
  }

export func fromRoman(s: string) -> int ! {} =
  fromChars(chars(s))

export func roundtrip(n: int) -> bool ! {} =
  if n >= 1 && n <= 3999 then fromRoman(toRoman(n)) == n else true

export func distinctEncoding(a: int, b: int) -> bool ! {} =
  if a >= 1 && a <= 3999 && b >= 1 && b <= 3999 && a != b then toRoman(a) != toRoman(b) else true

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

module benchmark/solution

import std/io (println)

export type SortedSet = SNil | SCons(int, SortedSet)

export func sLength(s: SortedSet) -> int {
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }
}

export func sMerge(a: SortedSet, b: SortedSet) -> SortedSet {
  match a {
    SNil => b,
    SCons(x, ra) => match b {
      SNil => a,
      SCons(y, rb) =>
        if x == y then SCons(x, sMerge(ra, rb))
        else if x < y then SCons(x, sMerge(ra, b))
        else SCons(y, sMerge(a, rb))
    }
  }
}

export func sIntersect(a: SortedSet, b: SortedSet) -> SortedSet {
  match a {
    SNil => SNil,
    SCons(x, ra) => match b {
      SNil => SNil,
      SCons(y, rb) =>
        if x == y then SCons(x, sIntersect(ra, rb))
        else if x < y then sIntersect(ra, b)
        else sIntersect(a, rb)
    }
  }
}

export func isSortedFrom(s: SortedSet, prev: int) -> bool {
  match s {
    SNil => true,
    SCons(x, rest) => if x > prev then isSortedFrom(rest, x) else false
  }
}

export func isSorted(s: SortedSet) -> bool {
  match s {
    SNil => true,
    SCons(x, rest) => isSortedFrom(rest, x)
  }
}

export func toStr(s: SortedSet) -> string {
  match s {
    SNil => "{}",
    SCons(x, rest) => "{${show(x)}${toStrRest(rest)}}"
  }
}

export func toStrRest(s: SortedSet) -> string {
  match s {
    SNil => "",
    SCons(x, rest) => ",${show(x)}${toStrRest(rest)}"
  }
}

export func mergePreservesSorted(a: SortedSet, b: SortedSet) -> bool {
  isSorted(sMerge(a, b))
}

export func inclusionExclusion(a: SortedSet, b: SortedSet) -> bool {
  sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b)
}

export func main() -> () ! {IO} {
  let a = SCons(1, SCons(3, SCons(5, SNil)));
  let b = SCons(2, SCons(3, SCons(4, SNil)));
  println(toStr(sMerge(a, b)));
  println(toStr(sIntersect(a, b)));
  println(show(sLength(sMerge(a, b))));
  println(show(isSorted(sMerge(a, b))));
  println(show(mergePreservesSorted(a, b)));
  println(show(inclusionExclusion(a, b)))
}

