class SCons:
    def __init__(self, head, tail):
        self.head = head
        self.tail = tail

SNil = None

def isEmpty(s):
    return s is None

def sMember(x, s):
    if isEmpty(s):
        return False
    if s.head == x:
        return True
    if s.head > x:
        return False
    return sMember(x, s.tail)

def sInsert(x, s):
    if isEmpty(s):
        return SCons(x, SNil)
    if s.head == x:
        return s
    if s.head > x:
        return SCons(x, s)
    return SCons(s.head, sInsert(x, s.tail))

def sMerge(a, b):
    if isEmpty(a):
        return b
    if isEmpty(b):
        return a
    if a.head == b.head:
        return SCons(a.head, sMerge(a.tail, b.tail))
    if a.head < b.head:
        return SCons(a.head, sMerge(a.tail, b))
    return SCons(b.head, sMerge(a, b.tail))

def sIntersect(a, b):
    if isEmpty(a) or isEmpty(b):
        return SNil
    if a.head == b.head:
        return SCons(a.head, sIntersect(a.tail, b.tail))
    if a.head < b.head:
        return sIntersect(a.tail, b)
    return sIntersect(a, b.tail)

def toStr(s):
    if isEmpty(s):
        return "SNil"
    elements = []
    curr = s
    while not isEmpty(curr):
        elements.append(str(curr.head))
        curr = curr.tail
    return "SCons(" + ", ".join(elements) + ", SNil)"

def sLength(s):
    if isEmpty(s):
        return 0
    return 1 + sLength(s.tail)

def isSorted(s):
    if isEmpty(s) or isEmpty(s.tail):
        return True
    return s.head <= s.tail.head and isSorted(s.tail)

def mergePreservesSorted(a, b):
    merged = sMerge(a, b)
    all_from_a = all(sMember(x, merged) for x in getElements(a))
    all_from_b = all(sMember(x, merged) for x in getElements(b))
    no_extra = all(sMember(x, a) or sMember(x, b) for x in getElements(merged))
    return isSorted(merged) and all_from_a and all_from_b and no_extra

def inclusionExclusion(a, b):
    union_len = sLength(sMerge(a, b))
    intersection_len = sLength(sIntersect(a, b))
    a_len = sLength(a)
    b_len = sLength(b)
    return union_len + intersection_len == a_len + b_len

def getElements(s):
    if isEmpty(s):
        return []
    return [s.head] + getElements(s.tail)

A = SCons(1, SCons(3, SCons(5, SNil)))
B = SCons(2, SCons(3, SCons(4, SNil)))

print(toStr(sMerge(A, B)))
print(toStr(sIntersect(A, B)))
print(sLength(sMerge(A, B)))
print(isSorted(sMerge(A, B)))
print(mergePreservesSorted(A, B))
print(inclusionExclusion(A, B))

