    if 0 <= age <= 150:
        return Ok(age)
    return Err("Age out of range")

def calculate_retirement_years(age: int) -> Result[int]:
    if age < 65:
        return Ok(65 - age)
    return Err("Already retired")

def chain_results(age: int) -> Result[int]:
    result = validate_age(age)
    if isinstance(result, Ok):
        return calculate_retirement_years(result.value)
    return result

def main():
    for age in [30, 70, -5]:
        result = chain_results(age)
        if isinstance(result, Ok):
            print(f"Years to retirement: {result.value}")
        else:
