def contains(x, lst):
    """Check if node x is in the list."""
    return x in lst


def enqueue(x, queue):
    """Add node x to the end of the queue."""
    queue.append(x)


def bfs(graph, start):
    """Perform BFS from start node, returning nodes in visit order."""
    visited = []
    queue = []

    enqueue(start, queue)

    while queue:
        current = queue.pop(0)

        if not contains(current, visited):
            visited.append(current)

            # Find neighbors of current node
            for node, neighbors in graph:
                if node == current:
                    for neighbor in neighbors:
                        if not contains(neighbor, visited) and not contains(neighbor, queue):
                            enqueue(neighbor, queue)
                    break

    return visited


def main():
    # Define the graph as adjacency list
    graph = [
        (1, [2, 3]),
        (2, [4]),
        (3, [4, 5]),
        (4, []),
        (5, [])
    ]

    # Run BFS starting from node 1
    result = bfs(graph, 1)

    # Print visited nodes in BFS order
    for node in result:
        print(node)


if __name__ == "__main__":
    main()

