from __future__ import annotations

type Env = list[tuple[str, int]]

class Num:
    __match_args__ = ("value",)
    def __init__(self, value: int) -> None:
        self.value = value

class Var:
    __match_args__ = ("name",)
    def __init__(self, name: str) -> None:
        self.name = name

class Add:
    __match_args__ = ("left", "right")
    def __init__(self, left: Expr, right: Expr) -> None:
        self.left = left
        self.right = right

class Mul:
    __match_args__ = ("left", "right")
    def __init__(self, left: Expr, right: Expr) -> None:
        self.left = left
        self.right = right

class Let:
    __match_args__ = ("name", "value", "body")
    def __init__(self, name: str, value: Expr, body: Expr) -> None:
        self.name = name
        self.value = value
        self.body = body

type Expr = Num | Var | Add | Mul | Let

def lookup(name: str, env: Env) -> int:
    for n, v in env:
        if n == name:
            return v
    raise ValueError(f"Variable not found: {name}")

def eval(expr: Expr, env: Env) -> int:
    match expr:
        case Num(n):
            return n
        case Var(name):
            return lookup(name, env)
        case Add(left, right):
            return eval(left, env) + eval(right, env)
        case Mul(left, right):
            return eval(left, env) * eval(right, env)
        case Let(name, value, body):
            val = eval(value, env)
            new_env = [(name, val)] + env
            return eval(body, new_env)

def main() -> None:
    program = Let(
        "x",
        Num(5),
        Let(
            "y",
            Add(Var("x"), Num(3)),
            Mul(Var("x"), Var("y"))
        )
    )
    result = eval(program, [])
    print(result)

if __name__ == "__main__":
    main()

