    Node(Leaf(lv), v, r) => max_three(lv, v, find_max(r)),
    Node(l, v, Leaf(rv)) => max_three(find_max(l), v, rv),
    Node(l, v, r) => max_three(find_max(l), v, find_max(r))
  }

