# 1. Define State Type (3 variants)
@dataclass
class Idle:
    floor: int

@dataclass
class Moving:
    current_floor: int
    target_floor: int

@dataclass
class DoorOpen:
    floor: int
    timer: int

State = Union[Idle, Moving, DoorOpen]

# 2. Define Event Type (3 variants)
@dataclass
class Call:
    floor: int

@dataclass
class Tick:
    pass

@dataclass
class Arrive:
    pass

Event = Union[Call, Tick, Arrive]

# 3. Implement transition function
def transition(state: State, event: Event) -> State:
    """
    Takes a state and an event, and returns the new state.
    It must handle all combinations exhaustively.
    """
    match (state, event):
        case (Idle(floor), Call(target)):
            if target == floor:
                return DoorOpen(floor, 3)
            else:
                return Moving(floor, target)
        case (Moving(cur, target), Arrive()):
            return DoorOpen(target, 3)
        case (DoorOpen(floor, timer), Tick()):
            if timer > 1:
                return DoorOpen(floor, timer - 1)
            else:
                return Idle(floor)
        # Any other combination: Return current state unchanged
        # This includes Moving + Tick, Idle + Tick, etc.
        case _:
            return state

# 4. Implement display function
def display(state: State) -> str:
    """
    Takes a state and returns a formatted string.
    """
    match state:
        case Idle(floor):
            return f"IDLE @ floor {floor}"
        case Moving(cur, target):
            return f"MOVING {cur} -> {target}"
        case DoorOpen(floor, timer):
            return f"DOOR_OPEN @ floor {floor} ({timer}sec)"

