from dataclasses import dataclass

@dataclass
class Expr:
    pass

@dataclass
class Const(Expr):
    value: int

@dataclass
class Var(Expr):
    name: str

@dataclass
class Add(Expr):
    left: Expr
    right: Expr

@dataclass
class Mul(Expr):
    left: Expr
    right: Expr

def diff(expr: Expr, var: str) -> Expr:
    match expr:
        case Const(_):
            return Const(0)
        case Var(name):
            if name == var:
                return Const(1)
            else:
                return Const(0)
        case Add(left, right):
            return Add(diff(left, var), diff(right, var))
        case Mul(left, right):
            return Add(
                Mul(left, diff(right, var)),
                Mul(right, diff(left, var))
            )

def simplify(expr: Expr) -> Expr:
    match expr:
        case Add(left, right):
            left = simplify(left)
            right = simplify(right)
            match (left, right):
                case (Const(0), r):
                    return r
                case (l, Const(0)):
                    return l
                case _:
                    return Add(left, right)
        case Mul(left, right):
            left = simplify(left)
            right = simplify(right)
            match (left, right):
                case (Const(0), _) | (_, Const(0)):
                    return Const(0)
                case (Const(1), r):
                    return r
                case (l, Const(1)):
                    return l
                case _:
                    return Mul(left, right)
        case _:
            return expr

