from dataclasses import dataclass
from typing import Callable, List, TypeVar, Union

# Generic type variables for higher-order functions
A = TypeVar('A')
B = TypeVar('B')

# 1. Define Tree type using dataclasses for immutability and convenience.
@dataclass(frozen=True)
class Leaf:
    """Represents a leaf in the binary tree with a single integer value."""
    value: int

@dataclass(frozen=True)
class Node:
    """Represents an internal node in the binary tree."""
    left: 'Tree'
    value: int
    right: 'Tree'

Tree = Union[Leaf, Node]

# 2. Implement mapTree: Applies a function to every value in the tree.
def mapTree(fn: Callable[[A], B], tree: Tree) -> Tree:
    """Recursively applies a function to all values in a tree."""
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    else:
        return Node(
            mapTree(fn, tree.left),
            fn(tree.value),
            mapTree(fn, tree.right)
        )

# 3. Implement foldTree: Performs an in-order fold (reduce) over the tree.
def foldTree(fn: Callable[[B, A], B], acc: B, tree: Tree) -> B:
    """Performs an in-order fold over the tree values."""
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    else:
        # In-order: process left, then current, then right.
        left_acc = foldTree(fn, acc, tree.left)
        current_acc = fn(left_acc, tree.value)
        return foldTree(fn, current_acc, tree.right)

# 4. Implement treeToList: Converts the tree to a list via in-order traversal.
def treeToList(tree: Tree) -> List[int]:
    """Converts the tree to a list using an in-order traversal."""
    if isinstance(tree, Leaf):
        return [tree.value]
    else:
        return treeToList(tree.left) + [tree.value] + treeToList(tree.right)

# 5. Implement treeDepth: Calculates the maximum depth of the tree.
def treeDepth(tree: Tree) -> int:
    """Calculates the maximum depth of the tree."""
    if isinstance(tree, Leaf):
        return 1
    else:
        return 1 + max(treeDepth(tree.left), treeDepth(tree.right))

def main():
    """Main function to run the tree transformation pipeline."""
    # 6. Define the test tree structure.
    tree = Node(
        Node(Leaf(1), 2, Leaf(3)),
        4,
        Node(Leaf(5), 6, Leaf(7))
    )

    # Define the transformation functions.
    def double(x: int) -> int:
        return x * 2

    def add(x: int, y: int) -> int:
        return x + y

    # 7. Perform transformations and print the results as required.
    print(treeToList(tree))
    print(treeToList(mapTree(double, tree)))
    print(foldTree(add, 0, tree))
    print(treeDepth(tree))

if __name__ == "__main__":
    main()

