import std/io (println)
import std/option (Option, Some, None)

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)
type Subst = [(string, Type)]

pure func lookup(subst: Subst, name: string) -> Option[Type] =
  match subst {
    [] => None,
    (n, t) :: rest => if n == name then Some(t) else lookup(rest, name)
  }

pure func apply(subst: Subst, t: Type) -> Type =
  match t {
    TInt => TInt,
    TBool => TBool,
    TVar(name) => match lookup(subst, name) {
      Some(found) => apply(subst, found),
      None => TVar(name)
    },
    TFunc(a, r) => TFunc(apply(subst, a), apply(subst, r))
  }

pure func unify(t1: Type, t2: Type) -> Option[Subst] =
  match t1 {
    TInt => match t2 {
      TInt => Some([]),
      TVar(name) => Some([(name, TInt)]),
      _ => None
    },
    TBool => match t2 {
      TBool => Some([]),
      TVar(name) => Some([(name, TBool)]),
      _ => None
    },
    TVar(name) => Some([(name, t2)]),
    TFunc(a1, r1) => match t2 {
      TFunc(a2, r2) => match unify(a1, a2) {
        Some(s1) => match unify(r1, r2) {
          Some(s2) => Some(s1 ++ s2),
          None => None
        },
        None => None
      },
      TVar(name) => Some([(name, t1)]),
      _ => None
    }
  }

pure func showBinding(subst: Subst, name: string) -> string =
  match lookup(subst, name) {
    Some(t) => "${name} = ${show(t)}",
    None => "${name} = <unbound>"
  }

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    Some(subst) => {
      println(showBinding(subst, "a"));
      println(showBinding(subst, "b"))
    },
    None => println("No unification")
  }
}
